    "excerpt": "我看过上千个创业项目，我可以负责任的说创业讲布局，就是一个大坑。我常常听到创业者说“战略就是布局”；“我们要进行产品线布局”；“我们要进行渠道布局”。但真这么做，这个项目的前景不妙。为…",
    "body": [
      "我看过上千个创业项目，我可以负责任的说创业讲布局，就是一个大坑。我常常听到创业者说“战略就是布局”；“我们要进行产品线布局”；“我们要进行渠道布局”。但真这么做，这个项目的前景不妙。为啥？布局要有两个条件：1是，你能够看透行业终局。2是，你有非常非常多的资源。",
      "创业者这两个条件都没有。，那是要把自己当神仙。创业者开始能够掌握的资源也很有限。有限的资源，一分散布局，那就什么也干不好了。",
      "所以，创业公司的战略不能走大公司的路子。布局思路适合他们，不适合创业者"
    ],
    "sourceUrl": "",
    "sourceName": "赛道战略学堂文稿库"
