    "excerpt": "企业家精神的概念是有缺陷的。听到这里，你可能能会想，怎么可能？那可是德鲁克提倡的，中国那么多管理学者追捧的概念啊。",
    "body": [
      "企业家精神的概念是有缺陷的。听到这里，你可能能会想，怎么可能？那可是德鲁克提倡的，中国那么多管理学者追捧的概念啊。",
      "你先别急，听我说完。",
      "企业家精神核心是创业精神。内涵是创新、冒险、实干、合作。你品味一下，这个几点，强调的都是去即刻行动。我的博士导师，法国创业及战略学研究学者，欧盟经济战略委员会顾问，Vaillant教授，就认为企业家精神是个过时的，有缺陷的概念。",
      "这个概念的问题在哪里？",
      "忽视了最优秀的创业者，还需要学习能力和反思能力。90%的创业公司，都会在5年内倒闭。这些破产的创业者，大部分也都有创新、冒险、实干、合作的精神。对比，那些剩下的10%，还有最为成功的1%创业者，除了运气，学习能力、反思能力成了重要的差别点。",
      "我认识的优秀创业者，像名创优品的叶国富等，都是强大的学习者。",
      "为什么学习和反思，对成功创业那么重要？我研究发现，现在创业的环境那么复杂，不学习别人的成功经验，不善于反思公司的经验教训，只知道冒险的创业者，越勤奋越容易陷入盲干，折腾的困境。",
      "也就是企业家精神，鼓励行动，这是开发机会，必要条件。但不是成功创业的充分条件。最新的创业研究表明，成功的创业者还要有学习和反思能力。",
      "制定战略最难的什么？",
      "有粉丝问我，辅导企业制定战略，最大的困难是什么？"
    ],
    "sourceUrl": "",
    "sourceName": "赛道战略学堂文稿库"
