    "excerpt": "未来十年，我们要面对一个世界滞胀的时代。这个时代和我们每个人、每个公司都息息相关，大家都要做好准备。做国际贸易、做投资的朋友，更加要特别注意。",
    "body": [
      "未来十年，我们要面对一个世界滞胀的时代。这个时代和我们每个人、每个公司都息息相关，大家都要做好准备。做国际贸易、做投资的朋友，更加要特别注意。",
      "说一个宏观经济的话题，这个话题和我们每个人、每个公司都息息相关，大家要做好心理准备，未来十年我们要面对一个世界滞胀的时代。做国际贸易的朋友，你可一定要听完。为什么会做这个判断呢？按照货币理论，通货膨胀是由于生产效率下降的原因导致的。生产效率下降，单位成本的投入，产出就会变少。简单的说，东西的成本就会变贵了。你看全球由于制裁、战争、还要中美竞争，加上疫情，已经出现了持续性的逆全球化，人流、物流不通畅。这就导致整个世界的生产效率是在下降当中的。这已经成了不争的事实。比如，欧洲放着成本低，传输效率高的俄罗斯天然气不用，要用美国的油气或者从印度倒卖过来的高价的油气。这样欧洲的工业的生产成本就自然要大幅上涨。还比如，美国的半导体公司不能做中国的生意，那他们的总需求，或者说他的市场销售收入就会下降，这样他的资产回报率也就下降。而中国的公司呢？由于买不到高端光刻机，也就是只能自己投入研发成本去生产、制造。这导致我们的成本也在上升。",
      "而另外一方面，全球的总需求还在下降，世界的主要经济体，美国、欧洲、日本他们的货币宽松已经走到头了，现在都进入一个货币收缩周期中，美国已经开始带头加息了，这就会压缩负债，也就会压缩世界的总需求。你看一方面成本在上升，另外一方面总需求在下降，这样的话就形成了一个滞胀的局面。",
      "可以预见的事情，中美之间的竞争是长期竞争。世界最大的两个经济体之间的这种对抗与竞争，必会导致世界产业链的重新调整，世界经济格局的巨大变化，而技术的进步又是很缓慢的，因此整个世界的总生产效率下降，是个长期趋势，所以，创业或做国际贸易的朋友要特别注意了，要现在开始做好准备，应对滞胀时代，你对此有什么好的想法，可以留言告诉我。",
      "说一个坏消息，这个消息和我们每个人、每个公司都息息相关，大家都要做好准备。未来十年，我们要面对一个世界滞胀的时代。做国际贸易、做投资的朋友，更加要特别注意。",
      "为什么会做这个判断呢？按照货币理论，通货膨胀的原因是生长效率下降。生产效率下降，单位成本的投入，产出就会变少。简单的说，东西的成本变贵，价格不得不上涨。你看全球由于制裁、战争、还有中美竞争，加上疫情，已经出现了持续性的逆全球化，人流、物流不通畅。这就导致整个世界的生产效率是在下降当中的。这已经成了不争的事实。比如，欧洲放着成本低，传输效率高的俄罗斯天然气不用，要用美国的油气或者从印度倒卖过来的高价的油气。这样欧洲的工业的生产成本就自然要大幅上涨。同时，俄罗斯也因为制裁，不能进口廉价商品，他们的通胀也到达15%以上。还比如，美国的半导体公司不能做中国的生意，那他们的总需求，或者说市场销售收入就会下降，这样他的资产回报率也就下降。而中国的公司呢？由于买不到高端光刻机，高端芯片，也就是只能自己投入研发成本去生产、制造。这导致我们的成本也在上升。",
      "而另外一方面，全球的总需求还在下降，世界的主要经济体，美国、欧洲、日本他们的货币宽松已经走到头了，现在都进入一个货币收缩周期中，美国已经开始带头加息了，这就会压缩负债，也就会压缩世界的总需求。你看一方面成本在上升，另外一方面总需求在下降，这样的话就形成了一个滞胀的局面。",
      "可以预见，世界头号的两大经济体之间的竞争是长期竞争。要持续至少十年吧。这种对抗与竞争，必会导致世界产业链的不得不重整。甚至因为国际政治原因，人为粗暴打断市场配置，牺牲生产效率。美国的芯片法案就是这样的例子。能提高生产效率的技术进步，又发展缓慢，因此整个世界的总生产效率下降，是个长期趋势。",
      "所以，创业、国际贸易、做投资的朋友要放弃幻想，要做好准备。全球化带来的有利环境结束了，要面对滞胀时代。不过，对中国整体来说，也有好消息。在各国的经济基础对比中，中国工业产业链最全，又拥有光伏、新能源汽车两张未来世界经济中的王牌。坚持挺过去，未来的机会就必然更多。"
    ],
