    "excerpt": "好的公司战略，是有边界的。好战略要告诉团队，公司要做什么，还要告诉团队，公司不做什么。华为98年基本法说“为了使华为成为世界一流的设备供应商，我们将永不进入信息服务业。”，14年李斌说…",
    "body": [
      "没有边界，不是好战略",
      "好的公司战略，是有边界的。好战略要告诉团队，公司要做什么，还要告诉团队，公司不做什么。华为98年基本法说“为了使华为成为世界一流的设备供应商，我们将永不进入信息服务业。”，14年李斌说，蔚来汽车要做“一个高性能、高端的智能电动汽车”。华为、蔚来的战略，边界很清楚。相反，2014年，贾跃亭说，乐视要做要智能化、互联网化、纯电动化的“超级汽车”。超级、智能化、互联网化，和现在流行的，帮助、科技、新零售、数字化等等，都是没有明确边界、明确定义的概念。用这种词汇确定公司要做的事情，就属于没有边界。也就不是好战略。",
      "再举个例子，还记得红极一时的凡客吗？2011年后凡客迅速衰败。回过去看，陈年领导下的凡客，经营上，也特别没边界。2010年，陈年公开说“创新就是乱来”，“未来一年，凡客还是乱来的一年”。没有从战略上去约定，公司做什么，不做什么。凡客有的只是财务目标，5亿、20亿，100亿，战略上却没有确定公司做什么，不做什么。结果，很残酷。2011年中国电商环境的一个小调整，公司就垮了。后来，陈年反思说“大规模扩大SKU，是凡客犯下的最大错误之一”。“人生最大的困难就是自我局限”。是啊，这么好的创业机会，那么多融资，就这样被浪费了。搞成这样，陈年这个人，也就永远失去了投资人的信任。",
      "制定创业战略，要确定方向、目标，也要选择路径。天下的路，都有边界。无论是单车道、还是4车道、八车道，总是要有边界的。公司也一样，没有明确边界，就不是好战略。",
      "小鹏汽车的战略劫，某种程度上，也是来自于因为公司的边界问题。他们的战略中，有两个关键词，智能汽车、科技路线。这两个词，是不是，可以包含的内容太多了？边界不明显？或许就是在这样的经营方针下，16万到46万的车，小鹏也就都决策干了。结果，资源就被分散了，竞争一来，每个车型都没有干好。",
      "解密战略 科学创业",
      "为什么公司一定要有边界？",
      "为什么公司一定要有边界，因为，公司的资源有限，因为有市场就有竞争。即便创业者很牛，融资能力很强，刚创业就拿了很多钱，团队可以随便招。那样公司也必须有边界。为啥，创业者的精力，时间还是有限的。在厉害的人，一天也只有24小时。人做的事情一多，就会乱，事情就抓不细。而且，有市场，就有竞争，只要竞争，就不是能不能做的问题，而是能不能比别人做得更好的问题。智商160的天才成就，往往成就没有智商120的专才大，为啥？天才选择太多，不能专注，不能持之以恒。公司也一样，明确边界了，才能集中资源，才能够有积累，才会形成势能，才有机会成为伟大公司。",
      "那么，什么是公司的边界？边界体现在，什么东西自己做、什么东西找别人做；走什么渠道，不走怎么渠道；做什么产品线，不做什么产品线；做什么客户，不做什么客户。这些，明确了，边界也就清晰了。"
    ],
    "sourceUrl": "",
    "sourceName": "赛道战略学堂文稿库"
