    "excerpt": "公司战略三要素：目标、路径和支点。最难，也是最重要的是路径。路径是什么？能落地走，还能到目的地。缺了路径的战略，就是空中楼阁。是梦想。一梦想，或许能够激励人。梦想就是梦想，不能落地，没…",
    "body": [
      "公司战略三要素：目标、路径和支点。最难，也是最重要的是路径。路径是什么？能落地走，还能到目的地。缺了路径的战略，就是空中楼阁。是梦想。一梦想，或许能够激励人。梦想就是梦想，不能落地，没法执行。制定好的公司战略，不能是这样。所谓，定一个方向，确定一下目标，就叫制定战略，是误解。伟大的战略设计，“农村包围城市”、“持久战”都是讲清楚了，实现胜利目标的路径。那么多年过去，路径，成为了那个战略的名称。",
      "我常常听到一些，人说，我们公司的战略落地难，执行难。一般这种情况，十之八九，要么就是根本没路径，要么就是，路径制定错误，根本行不通。比如，我见过不少消费品创业的项目，都说要做品牌。可是并没有想好做品牌的路径。以为，给产品做一个定个位就是做品牌了。或者，有人稍微进了一步，认为，还要加上做广告。然后，实际操作中，花大量的钱买流量。可是，流量是一锤子买卖，不能引发客户的传播，是一个销售手段，本质上不能是做品牌的路径。也就是，用流量投放的方法做品牌，也是行不通的。",
      "缺乏路径、或者路径不对，公司的发展目标，当然就实现不了。",
      "解密战略 科学创业"
    ],
    "sourceUrl": "",
    "sourceName": "赛道战略学堂文稿库"
