    "excerpt": "做公司，常常有人说，要接势。那什么是势？对做企业来说，势就两种。一种是机会，一种是资源。雷军说的，台风来了，猪都会飞。",
    "body": [
      "做公司，常常有人说，要接势。那什么是势？对做企业来说，势就两种。一种是机会，一种是资源。雷军说的，台风来了，猪都会飞。",
      "这里的风势，就是机会。是当时移动互联网普及，带来的智能手机的强大需求。这种借势，是借机会。",
      "京东上市前，引入腾讯入股，让腾讯成为京东第一大股东。作为腾讯入股条件，京东就获得了微信的一级入口。这个交易，也是一种借势。这种借势，是借资源。通过这个微信这个资源，让京东拥有了一个巨大的流量入口。",
      "创业，要能够高速发展，一定要能借势。纯粹靠自己公司的团队，硬去推动市场，教育市场。那个太难，太费劲。创业者思考战略，很重要的内容，就要去发现什么势可以借。",
      "创业战略，让创业少走弯路。",
      "大事件，跨国车企高管包机看车展",
      "这次上海车展，出现一个产业界，前所未见的大事件。欧洲的车企高管，包机前往上海看车展。你看奔驰股份董事长，宝马董事长、奥迪董事长，都来了。而且是，带着高管团队一起来。包机来，齐刷刷的来。他们来车展，还不是为了给自己品牌站台。主要是来看中国电动车最新产品。国家会展中心的外国人几乎是随处可见，这也使得本次上海车展备受全球汽车行业瞩目。",
      "媒体报道说，外国车企高管，在上海车展正经历“真相时刻”：原来中国电动车这么强了！疫情三年没有来看，现在一看，发现中国的电动车又进化了一大截。",
      "这个画面，是不是很像，以前中国企业去欧洲，去美国参加什么车展，电子展的情景？如今画面变了。变成了外国企业高管组团来中国学习。我们各种商业书籍当中那些顶顶大名，可以说有些高不可攀的标杆公司来中国学习造车。这真是有时空错乱，不真实的感觉。车展上，丰田汽车公司执行副总裁表示，丰田的做法应该是：虚心学习，要交付中国客户心仪的汽车。还有外国车企高管表示：中国消费者现在习惯把电动车里的空间作为“家的一部分”，这样的理念让他感觉很受启发；",
      "我大学时代，学汽车，那时教材上介绍的，要考的，都是外国车企发明的机械结构，制造技术。三十年过去，今天世界顶级车企来中国，学习我们的电动车怎么设计，用了什么技术，电池有什么性能。真是应了那句老话“三十年河东，三十年河西”。",
      "今天，中国电动车行业真真实实发生的事情，又一次展示了这样的一个事实。中国的资源基础已经很强大，只要机会来了，只要企业家经营思路正确，能够整合资源，集中注意力去抓机会，短短几年时间，就能做出撼动世界汽车行业百年格局的牛逼的事情。",
      "一切创业者，都可以从个我们正在经历的汽车行百年变局中学习。我绝对相信，今天发生的一切，将来都会被写入商业教科书，成为后面的企业管理者学习对象。无论干哪一行，是不是和造车相关，只要是创业者，都可以从中学习借鉴很多东西。",
      "创业战略，让创业少走弯路。"
    ],
