    "excerpt": "到处都是价格战，什么事情都有很多人在争，企业该怎么办？怎么才能让公司活下去？我看，任何一个过去有效的简单招数，现在都不行了。有人说，突破价格战，办法是找一个好定位？先不说，那么内卷的时…",
    "body": [
      "到处都是价格战，什么事情都有很多人在争，企业该怎么办？怎么才能让公司活下去？我看，任何一个过去有效的简单招数，现在都不行了。有人说，突破价格战，办法是找一个好定位？先不说，那么内卷的时候，找不找得到又是空白，又够大的定位。即便找到了，刚刚把市场教育完成了，才吃上一两口。对手就跟进了。还没来得及吃上红利，饭菜就被抢光了。期待通过定位来突破的企业，现在处于，既怕对手不跟进，又怕对手跟进太快。既怕做先烈，又怕便宜了别人。用重新定位来突围，是听起来容易，做起来难。",
      "好，换一个思路。把行业内卷，传递到公司内部，提高管理强度，压员工拼命加班。可现在的环境是，客户少了，定单少了，加班能有什么用。每个员工效率都高了，那就得更快裁员了。传闻某大厂，最近裁员2万人，带崩杭州未来科技城楼价。不是大厂管理水平低，员工不勤奋啊。实在是活少了。",
      "其他的，搞流程管理，搞股权分配，提供核心员工的积极性，这些招数，换以前公司好赚钱，业务蒸蒸日上的时候，都是提高公司战斗力的好办法，现在，工资都发不出去，员工哪里还在乎股权啊。",
      "那该怎么办？我说三个故事。",
      "刘备，刘皇叔，开始的时候，虽然已经是名满天下，还有，关羽、张飞这样武力值，强合伙人跟随。但还是，被曹操逼得到处流窜。直到不得已，三顾茅庐，请了了诸葛亮，得到了取巴蜀，占荆州的三分天下的战略，才发展起来。",
      "大革命各种失败，革命队伍士气低落。有人都公开问出了，“红旗到底打得多久”。当时的整个局面也可说是非常难，非常危险的。之后是怎么逆转的？也是，靠战略。教员针对性的提出，农村包围城市，这一伟大战略之后，逐步逐步就有了全面胜利。",
      "现在，建材、瓷砖行业难吧？最近和一个同学交流，他们企业，19年80亿，2022年做到了140亿？怎么做到的？他们采取的战略是，坚决布局一带一路国家。就把国内的这些处于衰退期的工厂，复制到非洲，南美洲。沿着产业转移，国家战略布局的大趋势走，按照这个战略，逆势获得了一个非常大的发展。",
      "内卷时代，对企业来说的困难时代，但却也是企业经营的战略时代。具有，战略能力的企业家会脱颖而出。机会导向、销售导向、技术导向的公司，都不够用了。战略能力会越来越重要。",
      "想让公司，抓住机会，从0到100持续业绩倍增，就更要有创业战略制定能力。",
      "今天，我把投资人压箱底的四大工具和战略三要素，整理成创业战略制定七步法，分享给大家。这套方法，系统完整。有大量案例，好学好用。点开评论区的链接，你就可以得到。",
      "学创业战略，让创业少走弯路！"
    ],
