    "excerpt": "你们知道，我给企业搞创业战略内训，给企业家私董会当教练，开创业战略制定培训课，发现最为普遍的问题是什么吗？说实话，当我接触到这个问题的时候，我开始以为这只是个别的创始人才有的问题，应该…",
    "body": [
      "要习惯外部思维",
      "你们知道，我给企业搞创业战略内训，给企业家私董会当教练，开创业战略制定培训课，发现最为普遍的问题是什么吗？说实话，当我接触到这个问题的时候，我开始以为这只是个别的创始人才有的问题，应该不是什么普遍问题，可是当我一次又一次在不同的人身上，都发现这个问题的时候，我才感觉，这可能真的是一个普遍的大问题。",
      "什么问题？大部分人思考战略，思考公司要做什么，都是内部思维，不会外部思维。",
      "典型的内部思维，有三种情况，你可以对照一下：",
      "把自己的使命、愿景当成了做某一个业务的理由。有人就跟我说，我就想创造一个平台，让跟着我干事的人，都能够在这平台上轻松创业。这就是把自己的心愿，当成了做一个新业务的理由了。市场可不管你怎么想。不管你的愿望有多美好，用户只会购买他们喜欢的东西。不会为别人的梦想卖单。",
      "从已有的资源、技术出发，强行打包一个产品。在一次私董会上，有创业者就说，我们家族是做海产批发的，我自己学计算机，我们还有一个老中医的资源，所以，要做个元宇宙中医馆，里面提供VR冥想加深海原生胶原补品这样一个项目。好吧，这个样的产品，谁会喜欢？谁有需要？回答是，不知道。但是感觉这些东西综合在一起，特别强。",
      "以自己的需要，或问了几个身边的人，就以为了解了外部。典型的表达是，我感觉这个产品这么好，我很喜欢，而且我跟我身边的人介绍了，他们也都觉得好。于是就决定做了。",
      "内部思维如果用在管理上，焦点是如何提高内部运作效率、优化资源配置和发挥自身优势。那是对的。但是，用在创业，用在做创业的业务决策上，那是有问题的。",
      "为什么？因为，创业，发展新业务，必须要借势。必有要有外部机会。创业没有风口，靠团队强推，那哪里能成功啊。",
      "认识清楚，哪里有风口，什么客户才有这个需求，现在的竞品有啥弱点，这个市场空间有多大，行业成长速度是多少，这些方面的情况才更重要。创业者了解机会，了解客户，了解竞争对手，都必须从外部找答案。也就是，要有外部思维。",
      "进行战略决策，需要外部思维，这个道理很简单。但真能够，习惯性的做到，外部视角看待公司业务决策，现在看来，即便对一些创业多年的人来说，也不容易。",
      "如果你或你公司核心团队，想打破一下固有思维，跳出既有局限，找到业务出路。可以找我，学习创业战略课。创业战略是我总结风险投资行业四大工具和战略三要素形成的，一套指导从0-100创业的方法。借助创业战略这个科学框架，和旁观者视角。可以帮助创业团队，迅速建立对战略决策的系统认识。",
      "学创业战略，让创业少走弯路！",
      "学战略，为啥比学管理难？",
      "学战略，为啥比学管理难？因为管理的针对的问题，用的概念都很具体。战略针对的问题，用的概念都很抽象。管理核心概念，比如，流程、组织结构、股权设计、激励机制、KPI考核等等，这些管理概念概念指什么，都很好理解。",
      "战略核心概念，比如机会、资源、路径、支点、趋势、竞争、定位等，这里的任何一个战略概念，都是抽象的。抽象的概念背后，还要分解成一两层，才能是可以衡量，可以观察的内容。具体的可以直接观察的概念，当然就好理解，好学习。相反，抽象的当然就难学习，难把握。所以，学习战略，是要下功夫，还要跟着好老师。",
      "但战略，对企业来说，绝不是可有可无。再好机会，没有战略，也不会创业成功。特别现在，经济寒冬，各行业内卷，竞争惨烈。机会对了，战略错了，或者，走了弯路，就会掉队。比如，威马汽车，融资百亿，和蔚小理同时起步，但战略路径不清楚，现在也就掉队了。蔚来汽车、小鹏汽车，打开了局面，但后面的战略节奏，出现错误，现在也很难。再比如，在行业变局期，非常牛X的，500强公司，一个的战略径失误，也是轻则丢掉领先地位，重则让公司破产倒闭。比如，数码相机崛起时代柯达，智能手机崛起时代的诺基亚、英特尔。在比如，现在新能源汽车时代，日本丰田等传统汽车企业。",
      "所以，要想创业成功，就要掌握创业战略制定的方法。这虽然难，但很重要。",
      "想要系统学习战略，找对人学。投资人最懂战略。今天，我就把投资人压箱底的四大工具和战略三要素，整理成创业战略制定七步法，分享给大家。这套方法，是顶级投资机构核心经验。有大量案例，好学好用。点开评论区的链接，你就可以免费得到。",
      "学创业战略，让创业少走弯路！"
    ],
