    "excerpt": "高中毕业的李想，搞的理想汽车打败名牌大学生搞的小鹏汽车和华为问界。马云也说过，阿里巴巴不招聘名校MBA。这证明创业能力与大学教育并没有直接关系。",
    "body": [
      "高中毕业的李想，搞的理想汽车打败名牌大学生搞的小鹏汽车和华为问界。马云也说过，阿里巴巴不招聘名校MBA。这证明创业能力与大学教育并没有直接关系。",
      "读大学学不到创业能力，这背后的道理也很清楚。大学里的教授，大多数是博士毕业后，直接留校任教。他们并没有切身的创业经验。对于如何经营管理企业，很多老师基本上也是束手无策。人是教不了，自己本身都不懂的知识。",
      "提高创业能力，主要要靠创业经验积累。如果，发现靠自己独自摸索，太苦，提高太慢。想要去学习，少走弯路。那也不能找错了人。要学，也要向有创业经验，懂创业的人学。如何创业，如何制定成功的，让公司持续发展的创业战略，仔细想想，也只有两种背景的人值得，创业者去学习去模仿。一类就是李想这种，连续创业成功的创业者，他们对创业过程理解得深刻。一类就投资人。投资人看的项目多，创业共性的东西总结得好。一个深，一个全，都值得去学。",
      "今天，我就把投资人压箱底的四大工具和战略三要素，整理成“创业战略制定七步法”，分享给大家。这套方法，系统完整，有大量案例，好学好用。点开评论区的链接，你就可以得到。",
      "学创业战略，让创业少走弯路！",
      "苹果发布 Vision Pro 灭了元宇宙幻想",
      "前几天，在苹果全球开发这大会上，苹果发布头显产品Vision pro。不用说，苹果的产品科技感十足。可以让用户从 VR 无缝过渡到 AR。在 12 个摄像头、5 个传感器和 6 个麦克风的支持下，用户可以用眼睛、声音和手势来控制这个系统。国内有人就说，苹果这个超级大公司终于要入局搞元宇宙了。应该给现在低迷的元宇宙生态，带来新势能。国内的元宇宙产业有救了。真的是如此吗？恐怕搞反了。苹果发布的Vision pro，其实是全面否定了Oculus，2012年成立以来，元宇宙十年的发展路径。是对，现有元宇宙的颠覆，所以，元宇宙支持者有什么好高兴的？",
      "看一看，Vision Pro的定价，3499美元，比现在的主流品牌Oculus贵十倍。这个产品价差，明显就是看不上现有元宇宙生态，表明了苹果打算推倒重来。重新劈开一条路，而不是在现有的赛道上前进。对于，现在已经上船的元宇宙创业者来说，他们之前的投入，设想的公司玩法，给投资人讲的故事，都得要从来，重新想。毕竟之前的说法，做法，计划，都是参照Oculus的设想的赛道来做的。",
      "可是，现在换赛道，拥抱苹果可行吗？难，不行。因为，Vision Pro 3499美元这个定价，代表着苹果公司现在还认为，头显类产品，还没有发展到，能够进入大众市场时候，他们现在还只是想，针对极少数富有的极客玩家，打磨产品。这对国内各城市里面都有的元宇宙孵化项目来说，这就尴尬了。苹果不想带你们玩。那现在还继续玩不玩？",
      "对了，马斯克对元宇宙头显的，评价是，把电视机架在鼻子上。真的有必要这么做吗？",
      "创业选择比努力更重要。选对路径，成功才不难。",
      "学创业战略，让创业少走弯路！",
      "所谓执行力不行，都是战略能力不够",
      "蛮多企业老板，老是抱怨团队的执行力不够。所谓执行力不行，都是战略能力不够。",
      "我认同他的这个观点。战略能力不够，制定出来的战略，不切实际，行不通。当然，就导致团队换了一茬又一茬，公司还是在原地打转。",
      "真正的好战略，本来就要求，能用二流的干部、三流的员工，干出一流的业绩来。小米加步枪，也能打败武装到牙齿的对手。",
      "战略对了，资源聚焦，迭代不折腾，哪有什么特别难的事情，团队做不到的，说是团队素质不够，都是借口。除了科技公司的技术研发，其他99%的岗位，需要的知识含量，初中生就够了吧。",
      "如果，老板制定的战略，有目标，没有路径。就要好，告诉团队要去北京，却没有明确，坐飞机、还是开车去、还是做火车去，那团队执行起来当然乱糟糟。",
      "如果，老板制定的战略，没有明确边界。老是既要也要。那团队，自然陷入内部资源争斗，表明忙碌，实际上都在内部勾心斗角，相互拆台。",
      "如果，老板制定的战略，没有预见性。执行没有半年，战略就变了，那团队自然就对公司没有信心，干活三心二意。",
      "这几种情况下，所谓的执行力不够，其实都是战略能力不足。",
      "你对公司的战略，还有疑虑。可以尝试了解一下创业战略制定七步法。我把投资人压箱底的四大工具和战略三要素，整理成创业战略制定七步法，分享给大家。点开评论区的链接，你就可以得到。",
      "学创业战略，让创业少走弯路！"
    ],
