    "excerpt": "网上有个战略咨询大V说，战略的最高境界是懂得放弃。这真实胡说。懂得放弃，会取舍，只是战略的最低境界好不好。把懂得放弃就当成了最高境界，后面的战略的精髓还怎么领悟？",
    "body": [
      "网上有个战略咨询大V说，战略的最高境界是懂得放弃。这真实胡说。懂得放弃，会取舍，只是战略的最低境界好不好。把懂得放弃就当成了最高境界，后面的战略的精髓还怎么领悟？",
      "第五次反围剿失败，李德看不行了，和博古决定放弃江西革命根据地，进行战略大转移。也就是开始长征。放弃江西根据地，打不赢了就跑。这个决策当然是正确的，毕竟保存革命的核心队伍。但这种放弃，算什么战略的最高境界？李德这个德国人，战略入门了没有，都很难说。",
      "零跑汽车，看到特斯拉model3打价格战，赶紧放弃完全纯电路线，搞增程式C11。用三个月保住了造车新势力前三的位置。这也是正确的选择，但可以说零跑汽车达到了战略的最高境界吗？不能吧。",
      "选择和取舍，不过是战略刚入门。战略的最高境界，不是懂得放弃，而是无功而胜。",
      "伟人用持久战这一战略，把当时强大的日本军队，拖入到人民战争的汪洋大海，看上去没有打什么大战，却消耗掉了日本的战争潜力，让中国，以弱胜强，取得了抗日战争的胜利。这才是高明的战略。",
      "增程式汽车，不过是自带充电宝的电动车，技术上并不难。但理想汽车凭借这一战略选择，现在取得了出人意料的成功。已经在造车新势力中，遥遥领先。到现在多传统车企人，对理想汽车的胜利，还是非常不服气，老是攻击说，理想汽车没有技术，做起来不难。但面对火爆的市场，也又不得不跟着搞增程式汽车。这种无功而胜，用了难度不大的技术，行业最低的营销费用，创新的产品设计，取得了意想不到的成功。才是高明。",
      "制定战略，当然要取舍。但懂得了放弃，不过是战略的入门。看清楚市场，看清楚自己的实力，避实击虚，制定出，能够用很少的努力或资源投入，战胜强大对手，获得伟大成功，才是战略的最高境界。",
      "现在，经济寒冬，企业的钱少了，公司还要生存发展，好战略就更重要了。",
      "想提升战略认知水平？建议，跟着顶级VC学战略。投资人才真正有丰富的把企业从小，做到大的经验。",
      "向顶级VC学战略，让创业少走弯路！"
    ],
