    "excerpt": "现在经济正处在不确定性时代。企业经常遇到赛道塌方。你的车再好，驾驶技术再高超。碰到的赛道塌方，那也受不了。",
    "body": [
      "现在经济正处在不确定性时代。企业经常遇到赛道塌方。你的车再好，驾驶技术再高超。碰到的赛道塌方，那也受不了。",
      "前不久，财政部废止PPP有关文件，政府和社会资本合作的基础设施和公用事业项目，马上受到大影响。地方债务出现违约，ToG赛道的项目，马上前景不妙。教培新规出台，K12学科教育整个产业链上，英语、数学、在线教育等赛道项目，全军覆灭。房地产行业硬着陆，产业链上的销售中介、设计院、施工单位、家电、建材、地产广告赛道，都牵连受到重大打击。国内最大的地产代理之一的易居，濒临倒闭。2019年纳斯达克上市，号称中国产业互联网SaaS第一股的房多多，已经变成垃圾股。市值不到2000万人民币。",
      "赛道基础不仅会被政策动摇。技术变革也会动摇赛道。动力电池技术，动摇了燃油车赛道。好不容易建立起燃油车竞争力的长城汽车，市值连年下跌。抖音、淘宝等平台用上了AI大模型技术，流量算法月月更新，短视频内容、直播带货等赛道上的公司，变成了算法的韭菜，没有了成长空间。",
      "怎么认识这些经营变化？怎么理解这些变化对公司经营的影响？",
      "如果，你懂得投资人发明的赛道概念，就容易想明白，看明白。",
      "赛道是产业价值链中稳定、难以替代并且适合组建公司去做的价值环节。价值环节，受到技术变革、政策冲击，变得不稳定或者被替代的时候，赛道上的企业，就会风雨飘摇。这个时候，不管你的品牌有没有温度，公司的KPI考核是不是严格，搞没搞股权激励，会不会战略复盘，通通都没用，都挡不住企业要衰败。",
      "但是如果你，对赛道有深刻的认识，就可能发现，技术、政策改变，带来的新赛道崛起的机会。如果你还会分析，赛道要求的资源和能力是什么，就能带领公司，像新东方、学而思那样，在赛道发射危机时，成功的转向，捕获新赛道的机会，重新发展。",
      "所以，在今天这个不确定时代，仅仅是埋头苦干，搞管理，搞产品，公司还是走不了多远。原来，做投资才需要懂的赛道，现在，创业者，CEO，我看也都需要懂。只有用赛道的理论武装自己，才能应对这个糟糕的经济环境。让公司活得更久，获得更好。",
      "找对赛道，科学创业。",
      "什么是难而正确事 这次终于说透了",
      "创业要做难而正确的事，投资人张磊、郭广昌这么说。创业者刘强东、董明珠也这么说。可是这句话，背后的含义是什么，大家未必真的知道。",
      "多数人说的时候，嘴上也说要做难而正确的事。做的时候，往往是另外一回事。说的和做的不一致，就是没有真懂。",
      "怎么真懂？如果，你知道风险投资人发明的赛道概念。懂得赛道就是产业价值链上，稳定、不可替代，并且适合组建公司去的独立价值环节。那么难而正确就很好理解。",
      "难指的这个价值环节，价值要够厚，够稳定，难以被替代。容易的事情，就没有了门槛，大家都能来做。这样的事情，公司做不大，也赚不到什么钱。像系统集成商，虽然也是产业链的一环，算得上一个赛道。但是，这个环节价值太薄。沉淀不了什么独特的知识。所以，这类赛道的项目，做不大，毛利率也低。电商代运营、MCN这些赛道，也是这个问题。",
      "正确的事情，就是这个价值环节要真实存在。不是臆想出来的，是产业链上下游分工中，必然要有的一环。新能源车发展，就带动了自动驾驶芯片、激光雷达、空气悬挂等赛道机会。而智能驾驶系统，由于和汽车的整体性能关系太过紧密，就变成了乘车厂必须具备的核心能力。不能成为一个独立的产业价值环节。所以，百度、小马智行等选择做智能驾驶赛道，就属于，难是够难，但不正确事。",
      "如果是终端产品，那正确的事是要让人的生活，变得多快好省美。新茶饮赛道，把水果、奶盖和传统的茶结合在一起，创造出来了，年轻人也爱喝的品类。所以，也是正确的事情。",
      "创业，从选定赛道开始。创业要做难而正确的事情，其实，就是讲了赛道选择的一个标准。只是，如何事先知道这个赛道是不正确的，是不是难的。就还需要对赛道形成和演化的规律有所认知。",
      "找对赛道，科学创业。",
      "企业躲不掉的不确定性时代",
      "京东前CEO徐雷说我们不是在经济下行周期，而是一个时代的落幕。用经济周期理论，理解现在的环境，的确不够了。管理学对此有个总结，认为企业进入了VUCA时代（vuca是volatility，uncertainty，complexity，ambiguity的缩写）。简单说，管理学认为我们进入了一个不确定性时代。",
      "创业者，CEO们在不确定性时代，要有新的本事。",
      "以前经营企业，一旦公司走入正规，在行业里面站稳了脚跟。创业者最主要的工作就是，跑客户找机会，盯对手找差距，对内提目标，抓管理、带团队。再有精力一些，就去外部找资源。找人、找钱、找政府，找经销商、找供应商。",
      "你现在是不是还这样？CEO现在还这样，就走不远了。几年前，就不行了。不能仅仅考虑这些了。",
      "不确定性时代开启，创业，经营企业最大风险是，要频频面对赛道塌方。赛道塌方，赛道上的大大小小的企业，都会倒霉。12个省份停建缓建地铁等项目。去年小程序管理政策升级。美国国会通过审查对外投资方案，限制美元基金对华投资等等。",
      "都是近期的发生的，引起相关赛道塌方的事件。还不要说，前几年的，地产三道红线、教培新规、碳排放限制指标、亚马逊封店这些。都是让相关赛道企业，大批大批倒下。未来，出生人口剧降，婴幼儿奶粉、幼儿园、甚至学校这些赛道，也会出问题。",
      "我和很多的企业家交流下来，发现不确定性时代，对企业来说，最大特点就是，赛道基础，经常被动摇。这个时代，说民营企业没信心，专业上讲，就是对自己赛道的未来没信心。焦虑、恐慌都源于此。",
      "面对这样的环境，创业者怎么办了？改变不了时代，就去升维认知。学习新的战略理论，把赛道变化，也纳入到自己的认知里面。提前预见赛道塌方，随时准备抓住，新赛道机会。",
      "例如，AI大模型技术、太空探索、新能源、生物医药技术、电商出海、一带一路等等，这些产业崛起，正在开启很多条新赛道。成功捕获其中任何一个新赛道机会，公司又能迎来新的结构性增长。",
      "经常要换赛道，这样做企业，当然会比以前累。需要创业者，企业家不能躺在过往建立的舒适圈内，按照既定轨道发展。但是，时代转化，适者生存。赛道塌方，坚持和努力，是无法应对的。靠创业者可以通过学习新一代的战略方法，迎接时代挑战。",
      "找对赛道，科学创业。"
    ],
