    "slug": "source-archive-139",
    "title": "独角兽企业新增数下降的主因是什么？",
    "originTitle": "独角兽企业新增数下降的主因是什么？",
    "category": "创业与战略",
    "date": "",
    "tags": [
      "创业与战略",
      "原稿"
    ],
    "excerpt": "领导问独角兽企业新增数量下降的主因是什么？这真实一个好问题啊。好问题引发反思。反思，发现过去的问题，绝对是走出经济低谷的关键第一步。",
    "body": [
      "领导问独角兽企业新增数量下降的主因是什么？这真实一个好问题啊。好问题引发反思。反思，发现过去的问题，绝对是走出经济低谷的关键第一步。",
      "据统计，2023年中国独角兽数量虽以316家在全球位居第二，但过去一年新增仅15家，2022年这个数字是40家，而在2018年，这个数字是156家。",
      "对比来看，在2023年，美国独角兽增加179家。从全球来看，在过去一年全球新诞生了500多家独角兽企业，平均每周接近10家。也就是，这几年，我们的独角兽企业趋势，和世界的趋势完全背离了。",
      "我们都说现在创业的机会少了，做成大企业难度大了。可是，看看国外的新增独角兽数据，就发现，事实情况刚好相反。现在机会很多，新创公司从来没有像现在这样，容易做大。",
      "我做投资快二十年，经历过好几拨创业浪潮。按我的经验，技术突破，资本活跃，政策宽松，年轻人看好未来的时候，新创企业就腾出不穷。",
      "大家都知道，这几年以ChatGPT为代表的生成式AI技术大突破。而在AI技术加持下，小公司也能干大公司的业绩。创业从0到独角兽的时间非常短。AI创业公司Midjourney员工只有11人，收入就超过了1亿美元。就算OPENAI公司这样的AI领导企业，估值，接近900亿美金了，和比亚迪差不多。团队却只有700人。而比亚迪有22万员工。",
      "技术突破，做大收入的门槛降低，创业从0到独角兽的时间非常短，已经引发了欧美国家的新一波创业浪潮。",
      "我们的情况刚好相反。创业浪潮没了，新增独角兽企业变少。问题出在哪里？技术突破是全球性的，问题就只能出在，资本、政策和年轻人的信心上了。",
      "现在，美元基金萎缩，高瓴总部外迁，沈南鹏移民。国内创投机构募资难，VC活跃度大不如以前。",
      "年轻人创业的热情？说什么呢，现在是“恨一个人，就让他去创业吧”。创业失败，本该不影响一个人的家庭生活，个人财产。但我们过去几年，太多创业失败的人，不仅赔掉了几年的时光，还赔掉了自己后半辈子的人生。",
      "可是站在整个经济未来来讲，今天的新创独角兽公司，就是明天的科技产业领军企业。今天，新增独角兽企业少了，就会在新一波技术爆发中掉队，未来就会陷入被动。",
      "怎么办？这里的关键是，创造创业友好型社会环境。鼓励创新，包容创业失败。改变现有社会规则，惩罚失败的现状。改变创业失败就要打成社会底层，变成失信人，卖房卖车。妻离子散，高铁做不了，连微信支付都用不了的状况。有限责任就是有限责任。不能变成创业者的无限责任。创业失败的概率本来就很高，结果又这么惨。年轻人自然就会没了创业的勇气。",
      "还有就是，不要当心资本泡沫。只要风险投资基金，是社会募集来的，是外国募集来的。不是政府的钱，就不要怕资本泡沫。繁荣的本质就是有泡沫。不必限制，让市场自己调节就好。",
      "社会规则改动到位了，创业风险降低了，风险投资重新活跃起来。机会本来就有，新增独角兽自然就又会多起来。毕竟我们国家，聪明的人很多。想干成大事的人也不少。"
    ],
