    "excerpt": "看看汽车赛道，你就知道什么是企业战略竞争时代了！在这个时代，拼的是各个战略的好坏，拼的是公司 CEO 的战略认知水平！不是拼爹，也不是拼管理，甚至不是拼技术、用户洞察、资本、营销、销售…",
    "body": [
      "看看汽车赛道，你就知道什么是企业战略竞争时代了！在这个时代，拼的是各个战略的好坏，拼的是公司 CEO 的战略认知水平！不是拼爹，也不是拼管理，甚至不是拼技术、用户洞察、资本、营销、销售网络、品牌、生产规模、资源、政策支持这些单项能力，而是拼把这些或长或短、或有或无的单项能力糅合起来形成的战略！就是拼这个！",
      "随着新能源车的发力，现在的汽车行业格局是这样的：比亚迪一骑绝尘，短短几年就变成了世界第一大新能源车公司，规模达到了 300 万辆。紧随其后的是华为问界和理想这两家造车新势力，它们在高端新能源车市场快速扩张。而央企、地方国企和传统民企的销量要么停滞不前，要么下滑了 20%~30%。",
      "论资源，比亚迪、华为问界、理想汽车肯定比不上一汽东风这样的央企，也比不上上汽、广汽这样的地方国企。",
      "论技术，理想汽车一直被嘲笑技术落后，不懂汽车。",
      "论管理，丰田公司可是汽车界公认的最佳管理实践，理想汽车和比亚迪在日系生产管理面前，那都是徒子徒孙辈分。",
      "论规模，2019 年上汽集团卖了 620 万辆，东风集团卖了 360 万辆，广汽集团卖了 200 万辆，比亚迪只卖了 45 万辆，还不如长城汽车的 106 万辆。理想汽车更是只卖了 1209 辆。华为问界那时候还没入场呢，销量是 0。",
      "论人才，造车新势力这些年的主力人才，不都是从传统车企挖过去的吗？",
      "论品牌，奔驰、宝马、丰田、凯迪拉克，哪一个不是有亿万粉丝的强势品牌？比亚迪、理想，算啥呀？",
      "但就这么短短 4-5 年，汽车行业已经发生了翻天覆地的变化。以至于广汽老总曾庆洪都呼吁对手要讲武德，不要太卷了，要长期主义。这可真是稀罕事啊，不是向来只有民企呼吁公平竞争吗，怎么现在拿错剧本了？！",
      "怎么样，资源、品牌、技术这些是不是解释不了这样的变化？很明显，汽车行业格局大变化的关键差异，就在王传福、余承东、李想这三位领导者身上，就在他们主导制定的公司战略比其他车企高明上。",
      "同样是早早看到了新能源车趋势，看到了汽车产业的发展方向。但是吉利、长城没有像比亚迪那样，在 2010 年就开始忍受业绩损失，全力为电动车积累技术。更没有王传福那种不惜停产纯燃油车的决心。",
      "而汽车国企呢，可能已经习惯了依靠资源优势，依靠外国车企赚钱。他们看不见，也不相信汽车行业变局真的来了，总觉得外国车企会突然搞个大招出来，一下秒杀比亚迪、理想汽车。就算华为找上门去，希望通过技术合作帮助他们赶上智能车的竞争要求，他们也不接受。为啥？灵魂可以给外资，哪能给华为这样的民企呢？",
      "决策者的远见、勇气、战略水平，演绎了这次汽车行业大变局。",
      "我们知道，决定公司业绩的四大因素是赛道演化趋势、竞争对手压迫、公司组织能力，还有 CEO 的战略选择。在历史的某个特定时期，其中某一个会起决定性作用。在汽车行业过去这几年，决定性的就是 CEO 的战略选择。",
      "一家汽车企业，过去几年，你可以错过管理数字化，可以某一款车型设计失误，也可以遭遇公关危机，品牌被水军围攻，甚至可以供应链出问题，断货半个月。但就是不能战略犯错。",
      "这就是企业战略竞争时代的特征。",
      "在这个不确定性的时代，很多行业、很多赛道，都和汽车行业一样，处于战略竞争期。",
      "如果你想快速提升战略能力，为公司找对赛道，制定好的战略路径，你可以学习赛道战略制定七步法。赛道战略模型，是我提炼 IDG 等顶级 VC 的方法论，专门为创始人、CEO 打造的战略规划方法。好学好用！",
      "用投资人的眼光，捕获赛道机会！"
    ],
