    "slug": "source-archive-146",
    "title": "从高考志愿到人生，经济学让你的选择更明智",
    "originTitle": "从高考志愿到人生，经济学让你的选择更明智",
    "category": "产业观察",
    "date": "",
    "tags": [
      "产业观察",
      "原稿"
    ],
    "excerpt": "都说选择大于努力，可你知道吗，专门研究选择的学科是经济学！就拿决定人生的一个重大选择，高考选大学，选专业来说吧。",
    "body": [
      "都说选择大于努力，可你知道吗，专门研究选择的学科是经济学！就拿决定人生的一个重大选择，高考选大学，选专业来说吧。",
      "想做出一个明智选择，就可以用四个经济学基本工具来分析分析。家长和考生都可以听听。",
      "第一，机会成本分析。选一个大学，得想想放弃另外一个大学的机会成本。你想报清华，那就要考虑放弃北大，就失去了北大的校友圈和自由学风啦。想去上海读大学，也得分析分析会失去家门口读大学才会有的爸妈的照顾和家族关系圈的庇护。比较过了机会成本，懂得了愿意放弃什么，剩下的才是更好的。机会成本分析，能避免情绪上头，被别人套路了。丢掉了你真正珍惜的。",
      "第二，成本效益分析。把某大学或专业的所有成本（像学费、生活费这些），还有预期收益（比如就业情况、职业前景、个人成长啥的）都列出来，计算一下。不同的选择，比如去深圳、上海、广州这些经济发达、企业多的地方，就业机会就会多不少。选那些正快速发展的大行业需要的专业，以后的职业前景就会好很多。比如人工智能、机器人、汽车、自动化、材料、生物医药这些方向。列出来，算一算就会发现，不同选择，投入产出比差别很大的。算清楚了，该选什么自然就清楚了！",
      "第三，个人偏好和价值观。经济学不否定个人偏好在理性选择中的重要性。孩子是想以后创办个伟大企业，赚大钱，还是想找个安稳工作，平凡快乐地生活；或者想搞研究，为人类贡献知识等等，这些内心深处的想法得听啊。尽量选跟这些因素相符的大学和专业。能找到一群志同道合的人，人生会快乐不少！",
      "第四，信息不对称。其实能帮你做选择的信息都是现成的，你不知道只是你没有去找而已。。张雪峰为啥这么火，不就是他收集了好多学校、专业的就业情况、职业发展的信息嘛。这些信息其实都是公开的，可以上网查、问老师、问学长学姐啥的。做选择，要努力收集信息，避免信息不对称导致的错误。",
      "机会成本、成本效益分析、个人偏好和价值观、信息不对称这四个经济学的基本工具，不光能帮你选大学、选专业，人生中其他重大选择，比如选对象、卖房子、选创业项目，都能用。因为，这就是无数人研究总结出来的，通用选择工具。",
      "说起来挺遗憾的，咱的基础教育体系是 50 年代设计的，70年基本没变。那时候整个社会的经济是按计划指令来运行的，每个人干啥都是组织安排的。个人只要努力提高技能，听话认真就行了，不需要懂咋做好选择。所以，基础教育中，就没有教经济学。",
      "知识结构中，没有经济常识的缺陷，导致每年都有很多家长、孩子盲目选大学，选专业。然后，后悔一辈子。",
      "教育使命，就应该帮助孩子成长，让他们为未来做好准备。人生，选择大于努力，所以经济学常识，中学就应该教啊。美国K12就有经济学课程。我们要尽早补上这一课。",
      "民营企业倒下会发生什么",
      "宁波上市公司博汇化工被要求补缴 5 亿税款，发公告宣布停产。知名品牌维维股份也发公告，提示可能要为枝江酒业补缴 30 年前税款。不仅中小微民营企业困难，上市民营公司也陷入困境。",
      "若民营企业纷纷倒下，会发生什么呢？",
      "首先是就业问题，中国劳动力人口 7.6 亿，体制内和国企提供了约 8000 万个工作岗位，另外 90%的工作岗位需依靠各类民营企业提供。民营企业倒下，就业将愈发困难，失业人口没钱，消费也难以刺激起来。大学生找不到工作，年轻人无所事事，肯定会影响社会秩序和安全。",
      "而且，民企倒下，国企日子也不好过。国企多为资源型企业，位于产业链上游，客户是下游民营企业。民营企业倒下，客户流失，国企也可能裁员倒闭。历史证明过这一逻辑，改革开放前，民营企业很少，国企普遍亏损严重，后来市场放开，民营企业发展壮大，国企收入利润才好转。",
      "如今，地产行业赛道塌方，建筑工程领域的央国企日子就难过，原因是他们的客户垮了。",
      "此外，创新创业也会低迷。创业公司多为民营企业，坚持几十年的中大型民企都难以为继，创业公司当然更是举步维艰。",
      "创业低迷，投资人找不到项目，资本市场也会低迷。有钱人宁愿存钱吃利息，也不投资，更不借钱投资。有资产信用的人不借钱，银行贷款放不出去，金融机构也会陷入困境。而且，国内找不到好的投资项目，资金就会外流，企业和资金就要出海！国内的企业和资金都出海了，外资当然就会来得更少了！",
      "民营企业是已经是我们市场经济的主体，稳住民营企业，就是稳住我们自己，也是稳住国家经济！",
      "民营企业 #经济 #就业 #国企 #创新创业 #资金外流"
    ],
