    "excerpt": "央行公布的社融数据可太直接了！4 月末 M1 同比下降 1.4%，5 月末 M1 同比下降 4.2%。这 M1 连续两个月像坐过山车一样快速下行，还同比负增长，这可是历史上第一次啊！",
    "body": [
      "央行公布的社融数据可太直接了！4 月末 M1 同比下降 1.4%，5 月末 M1 同比下降 4.2%。这 M1 连续两个月像坐过山车一样快速下行，还同比负增长，这可是历史上第一次啊！",
      "M1 数据代表企业手中的现金和短期存款。M1连续负增长，这经济到底咋了？光看宏观数据，咱也看不明白，也不敢下结论。那再来看看茅台酒的价格走势吧。",
      "茅台可不是一般的酒，那可是商务社交的名片啊！不管你爱不爱喝酒，谈生意、求人办事、搞搞关系的时候，有茅台酒，对方就觉得你倍儿尊重他。别的酒可没茅台这待遇，不管在山东、还是广东，不管是上海、还是北海，茅台酒都有这个超越其他酒的价值。",
      "有着这样的独特品牌价值在，茅台酒的价格，除了2012 年限酒令出台那几年，过去几十年就跟坐火箭似的，蹭蹭往上涨。看这图，2021年飞天茅台价格最高都超过 3000 了。茅台涨价的底层支持不是咱喝了多少白酒，而是商务社交的活跃度，也就是基建的投资力度，企业经营的活跃度，说白了，茅台酒价格走势反映的是经济繁荣度啊！",
      "有这个认知，再看这张茅台酒价格走势图，最近价格暴跌，这跟 M1 的数据简直是神同步啊！宏观货币数据和茅台酒价格，两种相互独立的数据，同时出现前所未有的变化。似乎都在说，企业不活跃了，企业家想躺平了，不愿意投资，不愿意扩大再生产，甚至不愿意请人吃饭，拉关系了。难道经济真的进入了 40 年都没见过的新局面？",
      "现在明明是夏天，可这怎么感觉像是到了三九严寒天呢？你们觉得呢？"
    ],
