    "excerpt": "扩大市场，创造市场。这解决眼下经济问题的关键啊！避免螺旋式下降，就得想办法让市场扩大起来。市场萎缩，企业没客户了，那就得关店，关厂，裁员。",
    "body": [
      "扩大市场，创造市场。这解决眼下经济问题的关键啊！避免螺旋式下降，就得想办法让市场扩大起来。市场萎缩，企业没客户了，那就得关店，关厂，裁员。",
      "稳经济、稳就业，重点在扩大市场。市场扩张了，需求自然就多了，企业也就会重新招聘，扩大生产啦。",
      "现在可不是谈分配问题的时候，钱没了，可不是只有穷人才没钱，富人中产的钱也在变少啊！我们的高中低端的消费都在下降，富人喝的茅台，穷人喝的啤酒，销量都在下滑呢。甚至一些上市公司老板，原来的亿万富豪，现在都可能倾家荡产了。收藏家马未都也陷入裁员欠薪丑闻。",
      "该给国民发钱就发钱，该扩大公共支出就扩大支出。虽然大家都在呼吁减轻企业负担，降低企业税负，减少行政对市场的干预，降低贷款利率。这些都是保护中小企、稳就业的重要举措，也都是当下必要的。但这还不够啊！",
      "市场和供应是经济等式的两端，现在主要是市场端出了问题，需求没了，所以各行各业都在卷，工厂、商铺、写字楼、电商，技术含量低的鞋服企业，高科技的光伏产业汽车产业，都在卷啊！可以说，到处卷。卷的企业家躺平打掼蛋，没有心思搞技术，找市场。",
      "不能再把资源用错方向了，创造市场、扩大市场才是当务之急啊"
    ],
