    "excerpt": "企业家就是企业家，他们既不是打工人，也不是资本家。如果思想还停留在亚当斯密、李嘉图、马克思的古典经济学时代，认为生产要素只是土地、劳动力和资本，就会搞不清企业家怎么归类，就会造成一会儿…",
    "body": [
      "企业家就是企业家，不姓“资”",
      "企业家就是企业家，他们既不是打工人，也不是资本家。如果思想还停留在亚当斯密、李嘉图、马克思的古典经济学时代，认为生产要素只是土地、劳动力和资本，就会搞不清企业家怎么归类，就会造成一会儿认为他们是资本家，一会儿认为他们是劳动者。",
      "其实，100 年前，熊彼特就已经发现，企业家是一个独立的生产要素。他们将资本和劳动力集合起来，创办企业，开展经营活动，承担相应的风险。光有资本和劳动力，没有企业家，工厂、企业根本办不起来。",
      "事实也是如此，看看我们今天的现实社会，资本、企业家、劳动力的分工已经很明显了。我们风险投资行业的工作，就是寻找优秀的创业者，给他们提供办企业的资本，帮助他们把企业经营好。马云、马化腾、雷军、张一鸣、刘强东，或者是最新的 Kimi 创始人杨值麟的创业故事，讲的不都是一个野心勃勃但没有资本的年轻人，被风险投资机构看上了，拿到大笔资金，成功搞起了他们的商业帝国的事。",
      "创业需要的基本能力，就是找钱、找人。也就是说，他们自己不是资本，也不是劳动力，而是一个单独的要素。",
      "作为一个独立的生产要素，企业家当然和劳动力，也就是员工之间会有矛盾、有冲突。事实上，企业家和资本也一样有矛盾和冲突。坦白说，投资基金、银行这些玩资本的，把创业者逼得倾家荡产，也是常有的事情。马斯克这样的企业家，和华尔街上的资本家，也一样矛盾重重。",
      "但是，有矛盾很正常啊，按照辩证法，共生要素之间的矛盾，正是推动社会进步的动力啊。",
      "认识清楚了每一个生产要素的独特性，把要素之间的冲突控制在良性互动的范围内，那矛盾就是建设性的力量，发展的力量。根本用不着当心和害怕。",
      "现在，真正的问题是，人们的认知普遍还在资本和劳动力的二元冲突的框架中，不知道怎么认识企业家。一会儿把企业家认定为资本家，是剥削者，是吸血鬼，是需要用法律去管束的对象；一会儿把企业家认为是创新者，是国家财富的创造者，给社会提供工作岗位，给员工发工资，是共同富裕的带头人，是国家必须鼓励支持的对象。",
      "经济困难，资本和劳动力的二元认知，已经让社会上对立情绪加剧。",
      "身处这样尖锐对立认知的环境中，企业家们，特别是没有后台的民营企业家们，心理苦啊。脑袋都被这两者冲突的认知给搞炸裂了，都想躺平了，没法安心搞企业，谋发展了。",
      "为啥就不能与时俱进，直接承认企业家就是企业家，他们是经济中不能少的关键自由因子，在资本和劳动力过剩的时代，企业家就是经济社会最为宝贵的一份子。我们经济要健康发展，就必须让企业家有安心搞企业的环境，并且还要给与他们足够激励，让他们有动力，用勇气点燃他们的创造力和进取心。"
    ],
