      "小米汽车的战略，为啥不是围绕小米生态？这个战略，雷军肯定考虑过，小米的团队也肯定努力过。但是，市场实战显示，女性苹果用户存在市场空白，才可能是小米汽车的核心客群。",
      "战略要稳定，但战略制定可不能死脑筋。制定战略是在变化的环境中找活路。找到了市场空白，就不要被使命、愿景、价值观干扰，甚至自己说过的话也别管。活下去才是最重要的！伟人说的“打得赢就打，打不赢就跑”，讲的就是这个道理。",
      "雷军能敏锐的抓住这个战略机会，公开喊出来，小米汽车要做支持苹果生态最好的汽车。",
