      "企业是环境的产物。中小企业老板现在很焦虑，为啥？环境变化太快了。看不清、看不懂环境变化，想不清经营思路。",
      "怎么办？建议抓紧时间提升战略能力。赛道战略七步法，是我总结 IDG 等顶级 VC 的方法论，专门为创业者、中小企业主打造的战略模型。不同于商学院讲的战略，赛道战略特别适合创业，或者开辟新业务的实战需要。好学好用。",
      "用投资人的眼光捕获赛道机会！",
