      "不能让经济战线的主力军，腹背受敌啊！经济战的主力是谁？那当然是企业啦！中美经济竞争早在几年前就已经打响，主将就是华为、比亚迪、大疆、字节跳动、Temu、希音、隆基绿能这些大型民企，还有千千万万做跨境电商的小商家，以及产业链上大大小小的制造业工厂。",
      "想要赢得经济战，想要变成发达国家，想要人均收入翻翻，就必须注意，别让这些经济战主力腹背受敌啊！别让他们，一面要应对美国有计划的脱钩封杀，一面还要被自己人骂成资本家，被抹黑，被排挤。",
