    "excerpt": "真是让人震惊啊！老板电器为了过冬，年收入110亿的公司，居然准备了 70 亿现金余粮！这家公司，买了 27 亿的理财，加上 43 亿的定期存款，手上竟然准备了 70 亿以上的现金储备！…",
    "body": [
      "真是让人震惊啊！老板电器为了过冬，年收入110亿的公司，居然准备了 70 亿现金余粮！这家公司，买了 27 亿的理财，加上 43 亿的定期存款，手上竟然准备了 70 亿以上的现金储备！🤯要知道，老板电器一年的管理费还不到 5 亿呢。这现金储备加利息，都快够公司管理人员 20 年的开销了！😱",
      "老板电器储备那么多现金干啥呢？是为了投资吗？不是的！2019 年之后，他们就没有出过手。我有个跟他们熟悉的学员就告诉我，现在的老板电器极度保守，再好的项目，不管是硬科技还是新品类的，他们都死活不投。😒完全就是一副保存现金、躺平过冬的姿态啊！😥",
      "这么一家有规模、有利润、完全没有生存忧虑的优秀龙头企业，居然采取这么保守的发展战略，可想而知，管理层对未来得有多悲观啊！😔龙头企业都没信心，不投资了，经济复苏的动力去哪里找啊？😫",
      "无人出租车的冲击：就业与生计的困境",
      "推广无人出租车，难道真的不管就业和底层人民的生计了吗？百度的无人出租车萝卜快跑在武汉落地，400 辆车靠着不到三分之一的价格优势，短短几个月就抢占了 45%的市场份额。先进的AI 技术对传统行业的颠覆力，真是强啊！听说北京、上海、广州这些更有影响力的城市，接下来也要跟进推广无人出租车了。",
      "但是，真的要这样吗？真的要用 AI 技术去抢几百万出租车、网约车司机的饭碗吗？作为投资人，我很清楚，AI 技术完全能让无人驾驶比人驾驶更安全。从产业趋势来说，无人驾驶出租车因为既便宜又安全，一定会成为主流。但正确的事，也得讲节奏和时机啊！出牌顺序错了，好牌也会输的。",
      "前不久，我听说广州火车站广场开始有人睡大街了，我还特意找了时间，晚上 9 点多去看了一下，发现这是真的。睡广场的有男有女，有些看着还是中年人。看到这场景，我心里真挺不是滋味的。90 年代的时候，很多人在家乡找不到工作，实在没办法，只能凑了几百块钱来广东碰运气。那时候，就有不少人因为钱花光了，又没找到工作，只好睡大街。只是后来经济发展了，这种现象就不常见了。变成一代人的痛，埋在心底。",
      "但现在，又能看见了。",
      "开网约车、跑外卖，可能是一些人的最后一份工作，给了他们做一个守法人的底线。要是这份工作没了，真不知道会怎么样。",
      "历史有时候，似曾相识。",
      "大家都知道，美国大萧条，可是很多人不知道，1910 年到 1933 年，是美国技术大爆发时期。电话、汽车、洗衣机、冰箱这些改变生活的重要产品，都是那个时候发明或者高速发展的。农业机械、电力和流水线的大规模普及，更是大大提高了农场、工厂、企业的生产效率。",
      "腾出不穷的发明创造，新公司快速成功，让人们对未来信心满满，夜夜笙歌。著名电影《了不起的盖茨比》就简述了这个历史。但是，没有人看到，技术爆发带来的负面因素也在积累。生产效率提升，劳动被技术替代，农民从乡村涌向城市。自动电话总机取代了成千上万的操作员；有声电影取代了黑白默片，让很多负责现场配乐的音乐家们失去了工作，大规模抗议活动时不时发生。经济要素之间的平衡被逐步打破，危机即将出现。",
      "1929年10月29日，美国股市暴跌，引发资产价值缩水，消费萎缩。企业开始出现一轮又一轮的裁员潮。经济呈现螺旋式下行。当时的胡佛政府采取贸易保护政策，并且鼓励企业降薪，过紧日子，客观上加剧市场收缩力度，最后造成了到1933年 GDP 下降 40%，失业率高达 29%的大萧条，社会痛苦不堪。",
      "可见，技术变革对经济和社会的影响很复杂，不是一定就会改善人们的生活。现在的经济环境，就业压力那么大，社会还能承受得了就业结构的大变化吗？有形的手，现在有必要去推动普及无人出租车这种会减少工作岗位的技术吗？",
      "审时度势，才不会进退失据，才不会让问题更严重啊！",
      "就业困境与大萧条的启示",
      "娃哈哈接班人宗馥莉请辞，饮料帝国何去何从？",
      "哇哈哈继承人宗馥莉竟然辞职了！她不仅不再担任娃哈哈集团总经理，还不再参与经营。而且，她还要求股东会尽快选出新的 CEO！这下可好，哇哈哈未来的掌门人是谁，成了一个大大的问号。不过，不管怎么说，宗馥莉接班失败，这已经是板上钉钉的事了。",
      "按照现在娃哈哈集团表面上的股权结构，地方国资是第一大股东，占股 46%。宗庆后持有 29.4%，剩下的则是工会持有 24.6%。创始人竟然不是第一大股东，就这种股权结构，说实话，没有创始人威望的二代想要顺利接班，那难度可太大了。",
      "娃哈哈是在 1987 年，由宗庆后承包杭州上城区校办企业创立的，从一开始就有国有成分的影子。作为一位杰出的创业者和企业家，宗庆后在世时，业务不断扩大，娃哈哈这个品牌也越来越响亮，公司更是越来越多。于是，就形成了错综复杂的各种合资、控股企业组成的娃哈哈关联体。这样做，虽然让宗庆后家族实现了对娃哈哈庞大资产的实际控制，但也导致了今天这种股权结构极度复杂、企业利益公私不分的局面。",
      "比如说，宗馥莉名下的宏胜饮料集团，就给娃哈哈做供应链配套。公平地说，这就是典型的关联交易。被人说成是利益输送，也不算过分。",
      "娃哈哈这个品牌，毫无疑问是宗庆后创立的，民间流传一种说法，宗老有一儿一女。女儿是宗馥莉，儿子是娃哈哈。按照我们的文化传统，局外的老百姓是希望看到宗馥莉接班。",
      "但是，习俗是习俗，法律是法律。股权的硬伤，国有资产的红线，曾经多次让娃哈哈的上市计划泡汤。那时，宗老还在，利益还没这么大。",
      "如今，在宗庆后去世5个月后，地方国资、宗庆后家族成员、高管、经销商等各种股东，或者管理层的利益矛盾，开始浮出水面了。矛盾看着要升级。",
      "宗馥莉权衡利弊，主动交权退出，从保护她个人人生安全的角度来看，这可真是个明智之举啊！接下来，饮料帝国娃哈哈集团，因为权力真空，肯定会动荡不安。娃哈哈这么好的民族品牌，真的好可惜啊，未来变得晦暗不明了。",
      "培养二代接班，企业实现基业长青，在全球来说，都不是一件容易的事情。在我们国有、民营二元企业制度下，就更加困难。",
      "不管怎么样，还是希望娃哈哈的利益相关者们，能够有足够的智慧和胸襟，处理好这个问题，找到合适的CEO。要知道，千亿娃哈哈渡过了这一关，上下游百万人的生计，就渡过了这一关。",
      "邹市明创业启示：别把方向当赛道！"
    ],
