    "excerpt": "赔掉多年积累，换来的教训是什么？不是不该创业，而是千万别把方向当赛道！",
    "body": [
      "赔掉多年积累，换来的教训是什么？不是不该创业，而是千万别把方向当赛道！",
      "邹市明曾说：“我们做的是拳击文化推广，包含培训、格斗、酒吧、餐厅、赛事等。”真可谓包罗万象🤔。夫妻二人还成立了 20 来家公司，创业决心很大，也够野心勃勃😮。",
      "邹市明是专业拳击手，又有美国经历，他对比中美拳击文化，发现差距显而易见。然后，结合自身 IP 优势，推动中国拳击文化发展，这创业思路总体没错✅。但文化推广只是方向，不是赛道🎯。赛道的颗粒度要到产品📦。",
      "就像李宁，看到中国体育用品市场的机会，做的却是运动服装👕。体育用品品牌是方向，运动服装才是赛道💪。",
      "认知不到创业要锁定的是赛道，而不仅仅是方向。邹市明同时进入至少 5 条赛道：拳击培训、健身馆、酒吧、餐厅、赛事组织😱。不同赛道，产品、竞争对手、资源都不同😣。创业进入多条赛道，再多钱也不够赔。",
      "现在是创业最难的时代，却也是不得不创业的时代。机会少了，就得少掉坑。现在，不少人受到数字经济、AI、新质生产力、出海这些概念吸引，投身创业。我提醒一句，这些还只是方向，想要成功还需要进一步明确赛道，以及路径。",
      "赛道战略七步法，是我总结IDG等顶级VC的方法论，专门为创始人打造。不同于商学院战略课，它特别适合创业和开拓新业务。",
      "用投资人的眼光捕获赛道机会。"
    ],
