      "其实，技术就像资本一样，作为生产要素之一，对社会的影响既有可能是善，也有可能是恶。关键在于企业家如何运用技术🤝。",
      "三聚氰胺用在化工、塑料工业中，可以提高材料的耐用性，是好技术；但被人用在奶粉中冒充蛋白质，就是坏技术。",
