      "用投资人的眼光捕获赛道机会。",
      "资本市场，要警惕的是市场失灵",
      "现在，市场失灵的现象挺多。",
      "制定战略最简单也是最重要的一步",
      "我们要站在世界看中国，不能站在中国看世界。如果站在中国看世界，可能会陷入两种极端：要么自大，觉得自己可以俯视其他国家，动不动就喊出震惊世界、要灭了谁谁谁的蠢话；要么自卑，习惯性地认为自己什么都不行，认为漂亮国就要摧毁我们的金融安全、粮食安全了，我们的外贸要被切断了，这些完全没有依据的事。",
      "只有站在世界看中国，我们才能生出平常心，能理性、客观地看到自己的机会、优势、差距和出路。",
      "创始人在给公司制定战略时也是如此。不能只站在企业内部看市场，找出路。因为使命、愿景、价值观这些主观东西，会限制你的视野。恐惧或自大，这些情绪可能会干扰你的判断。让你找不到用户的痛点，看不见机会，察觉不到威胁，不能客观地看清自己的优势和差距。",
      "要知道，你的公司的长处短板，公司发展战略的问题，别人往往一眼就看出来了。我们投资人这方面经验就很多。找我融资，或者找我咨询的项目，往往交流一个小时，我就能指出他们项目优缺点以及发展前景。",
      "现在是企业的战略竞争时代，创始人还是多走出办公室，时不时把自己切换成一个旁观者，通过找老师学习，和用户交流，从市场角度看企业。",
      "这是制定战略，为企业找到出路，最简单，也可能是最重要的一步。",
      "麦肯锡调查揭示消费群真相",
      "上半年的经济数据已经公布啦！GDP 增长了 5.0%，人均收入增长了 5.3%，失业率是 5.1%，比去年同期还下降了 0.2 个百分点呢。不过，这些数据和我们平时的感受好像有点不太一样哦。那到底是谁的收入真正增长了，消费也增加了呢？麦肯锡最近还真公布了一个调查报告，内容回答了这个问题呢。",
      "他们对国内的消费群体进行了分析，发现了五类特别有意思的人群。其中有三类人的信心很足，消费也很旺盛哦。第一类是“时代赢家”，也就是一线城市 58-65 岁的银发人群；第二类是“武德充沛基本盘”，是三线城市 42-65 岁的人群；第三类是“繁荣期长大的雏鸟”，就是一到四线城市的 18-25 岁的 Z 时代人群。",
      "另外还有两类人就比较悲观了，消费也在降级呢。一类是“时代燃料”，也就是一、二线城市 26 岁-41 岁的人，这些人就是我们身边的大多数啦；还有一类是“时代弃子”，是农村 42-65 岁的人。",
