    "title": "哈耶克突然被热议，这通常是因为市场机制出现了问题。你可以把这种情况想象成市场经济的“求救信号”，当它觉得自己需要帮助时，哈耶克的名字就会再次被提到。比如：",
    "originTitle": "哈耶克突然被热议，这通常是因为市场机制出现了问题。你可以把这种情况想象成市场经济的“求救信号”，当它觉得自己需要帮助时，哈耶克的名字就会再次被提到。比如：",
