    "excerpt": "1.政府干预的争议：当政府频繁地介入市场，试图通过各种清理行动、资格认证、资格许可来决定资源分配时，市场的自我调节能力可能会受到损害。这时，哈耶克的理论就会被拿出来，成为了一种反思和警…",
    "body": [
      "1.政府干预的争议：当政府频繁地介入市场，试图通过各种清理行动、资格认证、资格许可来决定资源分配时，市场的自我调节能力可能会受到损害。这时，哈耶克的理论就会被拿出来，成为了一种反思和警示。",
      "2.市场机制的失灵：如果一些领域出现，明明有需求，也有供应能力，但消费者不消费，企业家不投资，不扩张。市场经济开始显得有点“病怏怏”，哈耶克的理论可以帮助我们诊断问题的根源，寻找恢复市场活力的方法。",
      "3.计划经济的复兴：当管理者像个任性的指挥家一样试图将市场“管弦乐”全盘掌控时，哈耶克的理论被重新审视，仿佛是对这种过度干预的“警示牌”。",
      "哈耶克是那个站在历史的广场上，高喊“别用大锤子敲艺术品！”的人。他提醒人们，过度干预可能会让市场的自我调节能力失效，从而引发更大的经济问题。所以，当我们发现哈耶克的名字突然出现在各种讨论中时，也许是时候给市场经济的健康状况做个检查了。",
      "上了商学院的战略课，但是还是不知道自己的业务怎样才能实现结构性成长。那你可以试试赛道战略。赛道战略是我总结IDG等顶级VC的投资方法，专门为0-100的增长企业打造的战略模型。特别合适创始人破局内卷，开创新业务。好学好用。",
      "从焦虑中寻找业务破局的战略机会",
      "现在的人可真是太焦虑啦！焦虑业务增长，焦虑房贷的着落，焦虑孩子没有好大学，焦虑找不到对象……可以说，在一二线城市生活人，普遍焦虑！"
    ],
