    "slug": "source-archive-172",
    "title": "身为公司老板，或者CEO，每天面对的都是一堆难题啊客户搞不定，员工效率低，成本降不下来，研发进度慢…… 这可咋办？",
    "originTitle": "身为公司老板，或者CEO，每天面对的都是一堆难题啊客户搞不定，员工效率低，成本降不下来，研发进度慢…… 这可咋办？",
    "category": "创业与战略",
    "date": "",
    "tags": [
      "创业与战略",
      "原稿"
    ],
    "excerpt": "这时候，就得用问题导向的管理思维啦！就像拿着放大镜，仔细检查每一个细节，找出问题所在，然后一一解决。这种思维就像修修补补，让企业这台机器运转得更顺畅。",
    "body": [
      "这时候，就得用问题导向的管理思维啦！就像拿着放大镜，仔细检查每一个细节，找出问题所在，然后一一解决。这种思维就像修修补补，让企业这台机器运转得更顺畅。",
      "作为投资人，我判断创业者优不优秀，很重要的一点就是看他能不能在管理思维和战略思维之间找到平衡。优秀的创业者，不仅能发现和解决问题，还得有远见，能预见未来的危险和商机。一般人只能感知昨天，而优秀的创业者要知道明天会发生什么。",
      "问题导向的管理思维和未来导向的战略思维，就像经营企业的左右手，缺一不可。管理思维解决眼前问题，提高效率；战略思维规划未来，规避风险，把握机会。",
      "虽然这两种思维都是企业成功的关键，但在不同环境中，重要性也不同。环境稳定时，管理思维是基础；环境动荡时，战略思维是前提。",
      "实话实说，现在经济寒冬，企业经营环境动荡。作为投资人和赛道创业战略顾问，我的目标就是帮助创始人从过去的经济上行时代走出来，深刻理解这两种不同的思考方式，及时掌握未来导向的战略思维。",
      "赛道战略七步法是我提炼 IDG 等顶级 VC 的方法论，形成的方向、赛道、路径、策略、节奏的五层战略规划模型。可以把复杂多变的环境，梳理为清晰简单的业务发展路径。是专门为创业、开辟新业务准备的战略规划方法，好学好用。",
      "用投资人的眼光捕获赛道机会！",
      "💪# 管理思维 #战略思维 #企业成功 #投资 #战略顾问",
      "进行逻辑学教育：防范诈骗的根本！",
      "电信诈骗危害很大！为什么我们的受害者有那么多？不仅是骗子太狡猾，我们老百姓有时候太单纯啦！真要彻底治理电信诈骗，不仅要靠防，最好从源头上解决，比如加强教育，提高大家逻辑思考能力。",
      "现在我们是怎么做的？有些地方为了防诈骗，居然单方面限制银行卡交易额度。一次，只能取500、1000的，这招听起来挺狠，可实际上效果一般般啊！而且还违反存取自由的法律规定，让银行成了背锅侠，挨了不少骂呢！可以说，这做社会成本高，效果差，不是长久之计呀！",
      "我认为，最有效的方法还得是从教育做起，从根本上提高全民的逻辑水平。具体来说，就是在基础教育阶段开设逻辑课程。逻辑学听起来可能有些高大上，但实际上它是一门非常实用的学科，它教会我们如何思考，如何辨别真假，如何不被骗子牵着鼻子走。！",
      "因为，逻辑学讲的就是推理规律，训练的就是思辨能力。学会逻辑学，我们就能明白啥是靠谱推理，啥是胡说八道。这样一来，骗子的套路和陷阱，一眼就能识破，让他们无处遁形！",
      "比如说，骗子常用 “情感绑架”，利用咱同情心或贪婪心理，让人不知不觉就上当了。但要是学过逻辑学，就能很快识破这把戏，不会被他们牵着走！",
      "再比如说，骗子喜欢用似是而非的 “证据” 忽悠人，可能拿出些看起来很专业的数据或图表，让大家觉得他们说的是真的。可如果有逻辑学基础，就能很快发现这些所谓 “证据” 其实漏洞百出，根本站不住脚！",
      "不仅如此，逻辑学还是现代科学的基础，学逻辑学，还能帮助孩子们在学习数学、物理、化学、经济学等学科时更加得心应手。",
      "所以说，逻辑教育不仅能帮咱防范电信诈骗，还能提高咱整体素质呢！咱逻辑水平上去了，骗子生存空间自然就小了，电信诈骗问题就能从根本上解决啦！",
      "遗憾的是，1988年，中学语文教材删除了有关逻辑学的教学内容，让孩子们失去了接受逻辑学教育的机会。这或许就是现在人们容易受骗的原因之一。",
      "呼吁尽快行动起来从中学开始，让逻辑课重新成为必修课。让孩子们从小就能接触逻辑学，接受思辨训练，培养正确的思考方式。这不仅能帮助他们更好地迎接科学时代、AI时代的挑战，也能让他们不易上当受骗！",
      "逻辑教育 #防范电信诈骗 #低成本高效益"
    ],
