    "slug": "source-archive-173",
    "title": "从业余心态到职业素养：创业者的必经之路",
    "originTitle": "从业余心态到职业素养：创业者的必经之路",
    "category": "创业与战略",
    "date": "",
    "tags": [
      "创业与战略",
      "原稿"
    ],
    "excerpt": "创业最怕的，就是用业余的心态去做职业的事情。既然选择了创业，那它就已经是一条职业道路了，对吧？一旦开始创业，你的时间、精力和金钱都要投入其中，未来的前途也要靠创业来赢得。所以创业不是一…",
    "body": [
      "创业最怕的，就是用业余的心态去做职业的事情。既然选择了创业，那它就已经是一条职业道路了，对吧？一旦开始创业，你的时间、精力和金钱都要投入其中，未来的前途也要靠创业来赢得。所以创业不是一时冲动，而是一个职业选择。然而，很多创业者依然抱着业余的心态或思维在行动。比如，问他们为什么创业，他们会说：“我喜欢创业”或者“我有个技术”或“做了个专利”，所以就决定做项目了。这其实是很业余的想法。创业，首先要发现市场机会，也就是要洞察用户的痛点，找到行业里现存的问题，才能着手去做。机会来自外部，所谓的风口、趋势，都是外部环境变化带来的。你自己的动机和资源只是起点，如果只顾自己，凭兴趣做事情，那就还是业余思维。",
      "再比如，有些创业者把精力全放在研究产品功能、商业模式或者流量玩法上，却忽视了对成本结构的计算。他们好像觉得只要产品做出来了，创业就算成功了。这也是一种业余的思维。公司要赚钱，才能生存下去，创业者必须要会算账。能否做出成本结构分析、建立财务模型，并且清楚地计算出单店或公司整体的盈利模型，才是创业的基本能力，也是达到职业水平的最低标准。",
      "学赛道战略，科学创业。",
      "从上海到全国，服务消费补贴的热潮来袭！",
      "央行通过降存量房贷利率放水，地方要靠消费补贴来刺激市场。这次上海推出了5亿的服务消费补贴方案，餐饮拿了3.6亿，住宿9000万，电影3000万，体育2000万，精准打击到服务业的痛点。这才是正确的路子，面对通货收缩，中央和地方必须联动，把资源集中投向提升消费力。",
      "中央和地方其实就是应该这样分工明确，协同发力。中央搞全国性的政策，比如降房贷利率这种大动作，而地方则更接地气，针对本地市场，出台一些灵活的补贴政策。像上海这样，把钱主要花在服务消费上，是非常务实的做法。",
      "为什么服务消费值得地方政府集中补贴？因为它是真正的本地消费、本地生产，像餐饮、住宿、电影，甚至房地产这些行业，消费和生产基本都能在本地完成，钱转来转去还是留在本地，能最大程度带动地方经济。而家电、汽车这些东西，地方补贴了，结果钱很可能流到了其他地方的工厂，根本拉动不了本地经济。所以，集中在服务业，房地产行业的补贴，才能真正盘活地方经济。",
      "上海这次的做法算是开了个好头，估计广州、深圳等地很快就会跟上。如果大家都这么干，服务业的春天就快来了，相关的创业者和小企业也能迎来更多机会。",
      "不过，也要提醒一句，消费券的发放成本其实挺高的，远比直接发现金麻烦。如果忽略了发放成本，消费券可能会发不出去，最后没有起到刺激消费的效果。有些地方发的几亿消费券，实际到消费者手里的还不到五分之一。所以，补贴政策的效果，最终还是要看具体的执行细节。",
      "痛点就是机会。经济复苏不会一蹴而就，预计相关的窗口期会持续几年。这意味着，服务消费的补贴是个战略级别的机会。特别是服务领域的科技创业公司，可以借这个大趋势找到自己的战略机会点。",
      "如果对相关的方法论不太熟悉，欢迎来学习我的“赛道战略七步法”课程，或者看看我写的创业战略书。少走弯路，科学创业。",
      "用投资人的眼光，捕获赛道机会！"
    ],
