    "excerpt": "战略从来不是“要不要做”，而是“怎么做”。与其花几百万请咨询公司，不如先搞清楚：",
    "body": [
      "国家推数字化，你可以做某个垂直场景的AI工具；",
      "制造业出海火热，你可以专攻东南亚市场的售后服务体系；",
      "甚至像DeepSeek那样，用一个小突破撬动大趋势。",
      "战略从来不是“要不要做”，而是“怎么做”。与其花几百万请咨询公司，不如先搞清楚：",
      "1. 你的业务到底卡在哪个环节？",
      "2. 你能抓住的趋势里，哪些细节能变成突破口？",
      "3. 怎么用最低成本验证你的战略路径？",
      "（悄悄说，这本书里连实操模板都给你准备好了，翻一翻就能用了。）",
      "记住：战略不是选择题，而是连线题。连对了点，小公司也能撬动大时代。",
      "理想汽车 AI 转型，一场危险的游戏？",
      "今天咱来聊聊理想汽车的 AI 转型。李想提出要把理想汽车变成 “AI 公司”，这听起来好像挺厉害，符合科技趋势，但其实暗藏大问题哟！",
      "首先，这战略思维有盲区。李想陷入了AI、智能化这些大概念营造的逻辑幻境中。理想原来依靠洞察用户痛点，天才性选择增程式技术，走出了奶爸汽车的差异化路径，在造车新势力中脱颖而出。赛道是新能源车，路径是增程式家庭SUV。可现在的提出战略内含的赛道，从具体的汽车，变成了抽象的 AI，如果真的实施，就会造成公司的赛道漂移。赛道变了，理想团队，恐怕再也难聚焦在为用户造好汽车上。搞不好就迷失自己汽车制造商的身份，落到谁也不是的局面！",
      "其次，AI 只是技术不是产品呀！技术是有无数多种可能，同样的技术，可以各种各样的产品。但是，可做的产品多了，团队就会没了焦点，会迷茫。汽车行业是一个世界级竞争的行业，理想汽车虽然业绩不错，但底子其实还是很薄。和比亚迪、丰田汽车来比较，还差很远。一旦汽车属性弱化，团队心气散了，实际结果，就会造成战略执行难，就会失去电动车和智能驾驶的本质竞争力，给企业发展前景，蒙上阴影！",
      "看看人家何小鹏的最新采访，我觉得何小鹏经过2年多的拯救小鹏汽车的磨练，战略思维水平高了很多。他就说，小鹏汽车，只能是AI汽车公司，而不是AI公司。小鹏投资巨资搞AI，只是为让小鹏汽车更有竞争力，用户更喜欢他们家的车。这个战略思路，体现的还是汽车为本，技术为产品力服务，为赛道竞争服务的思想。显然，这才是对的。",
      "还有哦，投资人朱啸虎也批评理想自研 AI 大模型战略，说现阶段没意义，成熟开源技术够了，自研可能浪费时间资源。其实，朱啸虎在暗示，理想汽车你搞AI，但是能够搞得过的Deepseek、openAI这些主业就是大模型的公司么？这段时间Deepseek的先进大模型，开源了，一下就让你的研发投入化为乌有。",
      "总结一下，李想这 AI 转型战略，在人类进入AI时代的当下，听起来很有道理。但是如果你深刻体会了《创业战略》理论所讲的，战略是方向、赛道、路径、策略、节奏五个层次构成的一套决策。大概念只是适合思考方向，并不适合思考路径。明茨伯格曾警告说：“当战略沦为词语游戏，执行必然走向失控”。",
      "从这些战略理论能看出来，理想这转型战略，非常危险。会吃大亏！",
      "如果，你发现了重大机会，公司想要转型，急需要可靠的战略理论指导。可以来学习我的《赛道创业战略七步法》课程。课程内容把IDG等顶级VC的投资方法论和中国创业案例结合起来，形成了一套有体系的战略方法。是创业、开辟新业务的行动指南。好学好用。",
      "从战略高度，选好赛道，找新路径，应战时代大变局。",
      "口播文案：理想汽车AI转型，是豪赌还是自毁长城？"
    ],
